/// A data entry field that is preserved on an inlay hint between
/// a `textDocument/inlayHint` and a `inlayHint/resolve` request.
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct InlayHint {
    /// The position of this hint.
    ///
    /// If multiple hints have the same position, they will be shown in the order
    /// they appear in the response.
    #[serde(rename = "position")]
    pub position: Position,
    /// The label of this hint. A human readable string or an array of
    /// InlayHintLabelPart label parts.
    ///
    /// *Note* that neither the string nor the label part can be empty.
    #[serde(rename = "label")]
    pub label: StringOrInlayHintLabelParts,
    /// The kind of this hint. Can be omitted in which case the client
    /// should fall back to a reasonable default.
    #[serde(rename = "kind", skip_serializing_if = "Option::is_none")]
    pub kind: Option<InlayHintKind>,
    /// Optional text edits that are performed when accepting this inlay hint.
    ///
    /// *Note* that edits are expected to change the document so that the inlay
    /// hint (or its nearest variant) is now part of the document and the inlay
    /// hint itself is now obsolete.
    #[serde(rename = "textEdits", skip_serializing_if = "Option::is_none")]
    pub text_edits: Option<Vec<TextEdit>>,
    /// The tooltip text when you hover over this item.
    #[serde(rename = "tooltip", skip_serializing_if = "Option::is_none")]
    pub tooltip: Option<StringOrMarkupContent>,
    /// Render padding before the hint.
    ///
    /// Note: Padding should use the editor's background color, not the
    /// background color of the hint itself. That means padding can be used
    /// to visually align/separate an inlay hint.
    #[serde(rename = "paddingLeft", skip_serializing_if = "Option::is_none")]
    pub padding_left: Option<bool>,
    /// Render padding after the hint.
    ///
    /// Note: Padding should use the editor's background color, not the
    /// background color of the hint itself. That means padding can be used
    /// to visually align/separate an inlay hint.
    #[serde(rename = "paddingRight", skip_serializing_if = "Option::is_none")]
    pub padding_right: Option<bool>,
    /// A data entry field that is preserved on an inlay hint between
    /// a `textDocument/inlayHint` and a `inlayHint/resolve` request.
    #[serde(rename = "data", skip_serializing_if = "Option::is_none")]
    pub data: Option<InlayHintData>,
}

impl Decode for InlayHint {
    fn decode(value: &Value) -> Result<Self, DecodeError> {
        let object = expect_object(value)?;
        let mut position_ = None;
        let mut label_ = None;
        let mut kind_ = None;
        let mut text_edits_ = None;
        let mut tooltip_ = None;
        let mut padding_left_ = None;
        let mut padding_right_ = None;
        let mut data_ = None;
        for (name, value) in object {
            match name.as_str() {
                "position" => position_ = Some(Some(<Position as Decode>::decode(value)?)),
                "label" => {
                    label_ = Some(Some(<StringOrInlayHintLabelParts as Decode>::decode(
                        value,
                    )?))
                }
                "kind" => {
                    reject_null("kind", value)?;
                    kind_ = Some(Some(<InlayHintKind as Decode>::decode(value)?));
                }
                "textEdits" => {
                    reject_null("textEdits", value)?;
                    text_edits_ = Some(Some(<Vec<TextEdit> as Decode>::decode(value)?));
                }
                "tooltip" => {
                    reject_null("tooltip", value)?;
                    tooltip_ = Some(Some(<StringOrMarkupContent as Decode>::decode(value)?));
                }
                "paddingLeft" => {
                    reject_null("paddingLeft", value)?;
                    padding_left_ = Some(Some(<bool as Decode>::decode(value)?));
                }
                "paddingRight" => {
                    reject_null("paddingRight", value)?;
                    padding_right_ = Some(Some(<bool as Decode>::decode(value)?));
                }
                "data" => {
                    reject_null("data", value)?;
                    data_ = Some(Some(<InlayHintData as Decode>::decode(value)?));
                }
                _ => {}
            }
        }
        check_required(&[
            ("position", position_.is_some()),
            ("label", label_.is_some()),
        ])?;
        Ok(Self {
            position: position_.flatten().unwrap_or_default(),
            label: label_.flatten().unwrap_or_default(),
            kind: kind_.flatten(),
            text_edits: text_edits_.flatten(),
            tooltip: tooltip_.flatten(),
            padding_left: padding_left_.flatten(),
            padding_right: padding_right_.flatten(),
            data: data_.flatten(),
        })
    }
}

