impl Decode for Registration {
    fn decode(value: &Value) -> Result<Self, DecodeError> {
        let object = expect_object(value)?;
        let mut id = None;
        let mut method = None;
        let mut register_options = None;
        for (name, value) in object {
            match name.as_str() {
                "id" => id = Some(<String as Decode>::decode(value)?),
                "method" => method = Some(<String as Decode>::decode(value)?),
                "registerOptions" => register_options = Some(value),
                _ => {}
            }
        }
        check_required(&[("id", id.is_some()), ("method", method.is_some())])?;
        let method = method.unwrap_or_default();
        let Some(options) = register_options else {
            return Err(DecodeError(format!(
                "missing registerOptions for method: {method}"
            )));
        };
        Ok(Self {
            id: id.unwrap_or_default(),
            register_options: Some(RegisterOptions::decode_for(&method, options)?),
        })
    }
}

/// The method to unregister for.
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct Unregistration {
    /// The id used to unregister the request or notification. Usually an id
    /// provided during the register request.
    #[serde(rename = "id")]
    pub id: String,
    /// The method to unregister for.
    #[serde(rename = "method")]
    pub method: String,
}

impl Decode for Unregistration {
    fn decode(value: &Value) -> Result<Self, DecodeError> {
        let object = expect_object(value)?;
        let mut id_ = None;
        let mut method_ = None;
        for (name, value) in object {
            match name.as_str() {
                "id" => id_ = Some(Some(<String as Decode>::decode(value)?)),
                "method" => method_ = Some(Some(<String as Decode>::decode(value)?)),
                _ => {}
            }
        }
        check_required(&[("id", id_.is_some()), ("method", method_.is_some())])?;
        Ok(Self {
            id: id_.flatten().unwrap_or_default(),
            method: method_.flatten().unwrap_or_default(),
        })
    }
}

/// The workspace folders configured in the client when the server starts.
///
/// This property is only available if the client supports workspace folders.
/// It can be `null` if the client supports workspace folders but none are
/// configured.
///
/// Since: 3.6.0
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct WorkspaceFoldersInitializeParams {
    /// The workspace folders configured in the client when the server starts.
    ///
    /// This property is only available if the client supports workspace folders.
    /// It can be `null` if the client supports workspace folders but none are
    /// configured.
    ///
    /// Since: 3.6.0
    #[serde(rename = "workspaceFolders", skip_serializing_if = "Option::is_none")]
    pub workspace_folders: Option<WorkspaceFoldersOrNull>,
}

impl Decode for WorkspaceFoldersInitializeParams {
    fn decode(value: &Value) -> Result<Self, DecodeError> {
        let object = expect_object(value)?;
        let mut workspace_folders_ = None;
        for (name, value) in object {
            match name.as_str() {
                "workspaceFolders" => {
                    workspace_folders_ = if value.is_null() {
                        Some(None)
                    } else {
                        Some(Some(<WorkspaceFoldersOrNull as Decode>::decode(value)?))
                    };
                }
                _ => {}
            }
        }
        Ok(Self {
            workspace_folders: workspace_folders_.flatten(),
        })
    }
}

