/// Specifies whether the `data` field on a completion will replace or
/// be merged with data from `completionList.itemDefaults.data`.
///
/// If ApplyKind.Replace, the data from the completion item will be used if
/// provided (and not `null`), otherwise
/// `completionList.itemDefaults.data` will be used. An empty object can
/// be used if a completion item does not have any data but also should
/// not use the value from `completionList.itemDefaults.data`.
///
/// If ApplyKind.Merge, a shallow merge will be performed between
/// `completionList.itemDefaults.data` and the completion's own data
/// using the following rules:
///
/// - If a completion's `data` field is not provided (or `null`), the
///  entire `data` field from `completionList.itemDefaults.data` will be
///  used as-is.
/// - If a completion's `data` field is provided, each field will
///  overwrite the field of the same name in
///  `completionList.itemDefaults.data` but no merging of nested fields
///  within that value will occur.
///
/// Since: 3.18.0
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct CompletionItemApplyKinds {
    /// Specifies whether commitCharacters on a completion will replace or be
    /// merged with those in `completionList.itemDefaults.commitCharacters`.
    ///
    /// If ApplyKind.Replace, the commit characters from the completion item will
    /// always be used unless not provided, in which case those from
    /// `completionList.itemDefaults.commitCharacters` will be used. An
    /// empty list can be used if a completion item does not have any commit
    /// characters and also should not use those from
    /// `completionList.itemDefaults.commitCharacters`.
    ///
    /// If ApplyKind.Merge the commitCharacters for the completion will be the
    /// union of all values in both `completionList.itemDefaults.commitCharacters`
    /// and the completion's own `commitCharacters`.
    ///
    /// Since: 3.18.0
    #[serde(rename = "commitCharacters", skip_serializing_if = "Option::is_none")]
    pub commit_characters: Option<ApplyKind>,
    /// Specifies whether the `data` field on a completion will replace or
    /// be merged with data from `completionList.itemDefaults.data`.
    ///
    /// If ApplyKind.Replace, the data from the completion item will be used if
    /// provided (and not `null`), otherwise
    /// `completionList.itemDefaults.data` will be used. An empty object can
    /// be used if a completion item does not have any data but also should
    /// not use the value from `completionList.itemDefaults.data`.
    ///
    /// If ApplyKind.Merge, a shallow merge will be performed between
    /// `completionList.itemDefaults.data` and the completion's own data
    /// using the following rules:
    ///
    /// - If a completion's `data` field is not provided (or `null`), the
    ///  entire `data` field from `completionList.itemDefaults.data` will be
    ///  used as-is.
    /// - If a completion's `data` field is provided, each field will
    ///  overwrite the field of the same name in
    ///  `completionList.itemDefaults.data` but no merging of nested fields
    ///  within that value will occur.
    ///
    /// Since: 3.18.0
    #[serde(rename = "data", skip_serializing_if = "Option::is_none")]
    pub data: Option<ApplyKind>,
}

impl Decode for CompletionItemApplyKinds {
    fn decode(value: &Value) -> Result<Self, DecodeError> {
        let object = expect_object(value)?;
        let mut commit_characters_ = None;
        let mut data_ = None;
        for (name, value) in object {
            match name.as_str() {
                "commitCharacters" => {
                    reject_null("commitCharacters", value)?;
                    commit_characters_ = Some(Some(<ApplyKind as Decode>::decode(value)?));
                }
                "data" => {
                    reject_null("data", value)?;
                    data_ = Some(Some(<ApplyKind as Decode>::decode(value)?));
                }
                _ => {}
            }
        }
        Ok(Self {
            commit_characters: commit_characters_.flatten(),
            data: data_.flatten(),
        })
    }
}

/// The server supports the following `CompletionItem` specific
/// capabilities.
///
/// Since: 3.17.0
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct CompletionOptions {
    #[serde(rename = "workDoneProgress", skip_serializing_if = "Option::is_none")]
    pub work_done_progress: Option<bool>,
    /// Most tools trigger completion request automatically without explicitly requesting
    /// it using a keyboard shortcut (e.g. Ctrl+Space). Typically they do so when the user
    /// starts to type an identifier. For example if the user types `c` in a JavaScript file
    /// code complete will automatically pop up present `console` besides others as a
    /// completion item. Characters that make up identifiers don't need to be listed here.
    ///
    /// If code complete should automatically be trigger on characters not being valid inside
    /// an identifier (for example `.` in JavaScript) list them in `triggerCharacters`.
    #[serde(rename = "triggerCharacters", skip_serializing_if = "Option::is_none")]
    pub trigger_characters: Option<Vec<String>>,
    /// The list of all possible characters that commit a completion. This field can be used
    /// if clients don't support individual commit characters per completion item. See
    /// `ClientCapabilities.textDocument.completion.completionItem.commitCharactersSupport`
    ///
    /// If a server provides both `allCommitCharacters` and commit characters on an individual
    /// completion item the ones on the completion item win.
    ///
    /// Since: 3.2.0
    #[serde(
        rename = "allCommitCharacters",
        skip_serializing_if = "Option::is_none"
    )]
    pub all_commit_characters: Option<Vec<String>>,
    /// The server provides support to resolve additional
    /// information for a completion item.
    #[serde(rename = "resolveProvider", skip_serializing_if = "Option::is_none")]
    pub resolve_provider: Option<bool>,
    /// The server supports the following `CompletionItem` specific
    /// capabilities.
    ///
    /// Since: 3.17.0
    #[serde(rename = "completionItem", skip_serializing_if = "Option::is_none")]
    pub completion_item: Option<ServerCompletionItemOptions>,
}

impl Decode for CompletionOptions {
    fn decode(value: &Value) -> Result<Self, DecodeError> {
        let object = expect_object(value)?;
        let mut work_done_progress_ = None;
        let mut trigger_characters_ = None;
        let mut all_commit_characters_ = None;
        let mut resolve_provider_ = None;
        let mut completion_item_ = None;
        for (name, value) in object {
            match name.as_str() {
                "workDoneProgress" => {
                    reject_null("workDoneProgress", value)?;
                    work_done_progress_ = Some(Some(<bool as Decode>::decode(value)?));
                }
                "triggerCharacters" => {
                    reject_null("triggerCharacters", value)?;
                    trigger_characters_ = Some(Some(<Vec<String> as Decode>::decode(value)?));
                }
                "allCommitCharacters" => {
                    reject_null("allCommitCharacters", value)?;
                    all_commit_characters_ = Some(Some(<Vec<String> as Decode>::decode(value)?));
                }
                "resolveProvider" => {
                    reject_null("resolveProvider", value)?;
                    resolve_provider_ = Some(Some(<bool as Decode>::decode(value)?));
                }
                "completionItem" => {
                    reject_null("completionItem", value)?;
                    completion_item_ = Some(Some(<ServerCompletionItemOptions as Decode>::decode(
                        value,
                    )?));
                }
                _ => {}
            }
        }
        Ok(Self {
            work_done_progress: work_done_progress_.flatten(),
            trigger_characters: trigger_characters_.flatten(),
            all_commit_characters: all_commit_characters_.flatten(),
            resolve_provider: resolve_provider_.flatten(),
            completion_item: completion_item_.flatten(),
        })
    }
}

