/// The currently active `SignatureHelp`.
///
/// The `activeSignatureHelp` has its `SignatureHelp.activeSignature` field updated based on
/// the user navigating through available signatures.
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct SignatureHelpContext {
    /// Action that caused signature help to be triggered.
    #[serde(rename = "triggerKind")]
    pub trigger_kind: SignatureHelpTriggerKind,
    /// Character that caused signature help to be triggered.
    ///
    /// This is undefined when `triggerKind !== SignatureHelpTriggerKind.TriggerCharacter`
    #[serde(rename = "triggerCharacter", skip_serializing_if = "Option::is_none")]
    pub trigger_character: Option<String>,
    /// `true` if signature help was already showing when it was triggered.
    ///
    /// Retriggers occurs when the signature help is already active and can be caused by actions such as
    /// typing a trigger character, a cursor move, or document content changes.
    #[serde(rename = "isRetrigger")]
    pub is_retrigger: bool,
    /// The currently active `SignatureHelp`.
    ///
    /// The `activeSignatureHelp` has its `SignatureHelp.activeSignature` field updated based on
    /// the user navigating through available signatures.
    #[serde(
        rename = "activeSignatureHelp",
        skip_serializing_if = "Option::is_none"
    )]
    pub active_signature_help: Option<SignatureHelp>,
}

impl Decode for SignatureHelpContext {
    fn decode(value: &Value) -> Result<Self, DecodeError> {
        let object = expect_object(value)?;
        let mut trigger_kind_ = None;
        let mut trigger_character_ = None;
        let mut is_retrigger_ = None;
        let mut active_signature_help_ = None;
        for (name, value) in object {
            match name.as_str() {
                "triggerKind" => {
                    trigger_kind_ = Some(Some(<SignatureHelpTriggerKind as Decode>::decode(value)?))
                }
                "triggerCharacter" => {
                    reject_null("triggerCharacter", value)?;
                    trigger_character_ = Some(Some(<String as Decode>::decode(value)?));
                }
                "isRetrigger" => is_retrigger_ = Some(Some(<bool as Decode>::decode(value)?)),
                "activeSignatureHelp" => {
                    reject_null("activeSignatureHelp", value)?;
                    active_signature_help_ = Some(Some(<SignatureHelp as Decode>::decode(value)?));
                }
                _ => {}
            }
        }
        check_required(&[
            ("triggerKind", trigger_kind_.is_some()),
            ("isRetrigger", is_retrigger_.is_some()),
        ])?;
        Ok(Self {
            trigger_kind: trigger_kind_.flatten().unwrap_or_default(),
            trigger_character: trigger_character_.flatten(),
            is_retrigger: is_retrigger_.flatten().unwrap_or_default(),
            active_signature_help: active_signature_help_.flatten(),
        })
    }
}

/// A colorized label for the signature, providing classified text runs for VS syntax coloring.
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct SignatureInformation {
    /// The label of this signature. Will be shown in
    /// the UI.
    #[serde(rename = "label")]
    pub label: String,
    /// The human-readable doc-comment of this signature. Will be shown
    /// in the UI but can be omitted.
    #[serde(rename = "documentation", skip_serializing_if = "Option::is_none")]
    pub documentation: Option<StringOrMarkupContent>,
    /// The parameters of this signature.
    #[serde(rename = "parameters", skip_serializing_if = "Option::is_none")]
    pub parameters: Option<Vec<ParameterInformation>>,
    /// The index of the active parameter.
    ///
    /// If `null`, no parameter of the signature is active (for example a named
    /// argument that does not match any declared parameters). This is only valid
    /// if the client specifies the client capability
    /// `textDocument.signatureHelp.noActiveParameterSupport === true`
    ///
    /// If provided (or `null`), this is used in place of
    /// `SignatureHelp.activeParameter`.
    ///
    /// Since: 3.16.0
    #[serde(rename = "activeParameter", skip_serializing_if = "Option::is_none")]
    pub active_parameter: Option<UintegerOrNull>,
    /// A colorized label for the signature, providing classified text runs for VS syntax coloring.
    #[serde(rename = "_vs_colorizedLabel", skip_serializing_if = "Option::is_none")]
    pub _vs_colorized_label: Option<VSClassifiedTextElement>,
}

impl Decode for SignatureInformation {
    fn decode(value: &Value) -> Result<Self, DecodeError> {
        let object = expect_object(value)?;
        let mut label_ = None;
        let mut documentation_ = None;
        let mut parameters_ = None;
        let mut active_parameter_ = None;
        let mut _vs_colorized_label_ = None;
        for (name, value) in object {
            match name.as_str() {
                "label" => label_ = Some(Some(<String as Decode>::decode(value)?)),
                "documentation" => {
                    reject_null("documentation", value)?;
                    documentation_ = Some(Some(<StringOrMarkupContent as Decode>::decode(value)?));
                }
                "parameters" => {
                    reject_null("parameters", value)?;
                    parameters_ = Some(Some(<Vec<ParameterInformation> as Decode>::decode(value)?));
                }
                "activeParameter" => {
                    active_parameter_ = if value.is_null() {
                        Some(None)
                    } else {
                        Some(Some(<UintegerOrNull as Decode>::decode(value)?))
                    };
                }
                "_vs_colorizedLabel" => {
                    reject_null("_vs_colorizedLabel", value)?;
                    _vs_colorized_label_ =
                        Some(Some(<VSClassifiedTextElement as Decode>::decode(value)?));
                }
                _ => {}
            }
        }
        check_required(&[("label", label_.is_some())])?;
        Ok(Self {
            label: label_.flatten().unwrap_or_default(),
            documentation: documentation_.flatten(),
            parameters: parameters_.flatten(),
            active_parameter: active_parameter_.flatten(),
            _vs_colorized_label: _vs_colorized_label_.flatten(),
        })
    }
}

