/// Additional options used during matching.
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct FileOperationPattern {
    /// The glob pattern to match. Glob patterns can have the following syntax:
    /// - `*` to match zero or more characters in a path segment
    /// - `?` to match on one character in a path segment
    /// - `**` to match any number of path segments, including none
    /// - `{}` to group sub patterns into an OR expression. (e.g. `**​ .{ts,js}` matches all TypeScript and JavaScript files)
    /// - `[]` to declare a range of characters to match in a path segment (e.g., `example.[0-9]` to match on `example.0`, `example.1`, …)
    /// - `[!...]` to negate a range of characters to match in a path segment (e.g., `example.[!0-9]` to match on `example.a`, `example.b`, but not `example.0`)
    #[serde(rename = "glob")]
    pub glob: String,
    /// Whether to match files or folders with this pattern.
    ///
    /// Matches both if undefined.
    #[serde(rename = "matches", skip_serializing_if = "Option::is_none")]
    pub matches: Option<FileOperationPatternKind>,
    /// Additional options used during matching.
    #[serde(rename = "options", skip_serializing_if = "Option::is_none")]
    pub options: Option<FileOperationPatternOptions>,
}

impl Decode for FileOperationPattern {
    fn decode(value: &Value) -> Result<Self, DecodeError> {
        let object = expect_object(value)?;
        let mut glob_ = None;
        let mut matches_ = None;
        let mut options_ = None;
        for (name, value) in object {
            match name.as_str() {
                "glob" => glob_ = Some(Some(<String as Decode>::decode(value)?)),
                "matches" => {
                    reject_null("matches", value)?;
                    matches_ = Some(Some(<FileOperationPatternKind as Decode>::decode(value)?));
                }
                "options" => {
                    reject_null("options", value)?;
                    options_ = Some(Some(<FileOperationPatternOptions as Decode>::decode(
                        value,
                    )?));
                }
                _ => {}
            }
        }
        check_required(&[("glob", glob_.is_some())])?;
        Ok(Self {
            glob: glob_.flatten().unwrap_or_default(),
            matches: matches_.flatten(),
            options: options_.flatten(),
        })
    }
}

