/// Predefined error codes.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize)]
#[serde(transparent)]
pub struct ErrorCode(pub i32);

impl ErrorCode {
    pub const PARSE_ERROR: Self = Self(-32700);
    pub const INVALID_REQUEST: Self = Self(-32600);
    pub const METHOD_NOT_FOUND: Self = Self(-32601);
    pub const INVALID_PARAMS: Self = Self(-32602);
    pub const INTERNAL_ERROR: Self = Self(-32603);
    /// Error code indicating that a server received a notification or
    /// request before the server has received the `initialize` request.
    pub const SERVER_NOT_INITIALIZED: Self = Self(-32002);
    pub const UNKNOWN_ERROR_CODE: Self = Self(-32001);
    /// A request failed but it was syntactically correct, e.g the
    /// method name was known and the parameters were valid. The error
    /// message should contain human readable information about why
    /// the request failed.
    ///
    /// Since: 3.17.0
    pub const REQUEST_FAILED: Self = Self(-32803);
    /// The server cancelled the request. This error code should
    /// only be used for requests that explicitly support being
    /// server cancellable.
    ///
    /// Since: 3.17.0
    pub const SERVER_CANCELLED: Self = Self(-32802);
    /// The server detected that the content of a document got
    /// modified outside normal conditions. A server should
    /// NOT send this error code if it detects a content change
    /// in it unprocessed messages. The result even computed
    /// on an older state might still be useful for the client.
    ///
    /// If a client decides that a result is not of any use anymore
    /// the client should cancel the request.
    pub const CONTENT_MODIFIED: Self = Self(-32801);
    /// The client has canceled a request and a server has detected
    /// the cancel.
    pub const REQUEST_CANCELLED: Self = Self(-32800);

    /// tsgo's `String()`: the member's name, if the value is one.
    pub fn name(self) -> Option<&'static str> {
        match self.0 {
            -32700 => Some("ParseError"),
            -32600 => Some("InvalidRequest"),
            -32601 => Some("MethodNotFound"),
            -32602 => Some("InvalidParams"),
            -32603 => Some("InternalError"),
            -32002 => Some("ServerNotInitialized"),
            -32001 => Some("UnknownErrorCode"),
            -32803 => Some("RequestFailed"),
            -32802 => Some("ServerCancelled"),
            -32801 => Some("ContentModified"),
            -32800 => Some("RequestCancelled"),
            _ => None,
        }
    }
}

