/// A set of predefined code action kinds
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize)]
#[serde(transparent)]
pub struct CodeActionKind(pub Cow<'static, str>);

impl CodeActionKind {
    /// Empty kind.
    pub const EMPTY: Self = Self(Cow::Borrowed(""));
    /// Base kind for quickfix actions: 'quickfix'
    pub const QUICK_FIX: Self = Self(Cow::Borrowed("quickfix"));
    /// Base kind for refactoring actions: 'refactor'
    pub const REFACTOR: Self = Self(Cow::Borrowed("refactor"));
    /// Base kind for refactoring extraction actions: 'refactor.extract'
    ///
    /// Example extract actions:
    ///
    /// - Extract method
    /// - Extract function
    /// - Extract variable
    /// - Extract interface from class
    /// - ...
    pub const REFACTOR_EXTRACT: Self = Self(Cow::Borrowed("refactor.extract"));
    /// Base kind for refactoring inline actions: 'refactor.inline'
    ///
    /// Example inline actions:
    ///
    /// - Inline function
    /// - Inline variable
    /// - Inline constant
    /// - ...
    pub const REFACTOR_INLINE: Self = Self(Cow::Borrowed("refactor.inline"));
    /// Base kind for refactoring move actions: `refactor.move`
    ///
    /// Example move actions:
    ///
    /// - Move a function to a new file
    /// - Move a property between classes
    /// - Move method to base class
    /// - ...
    ///
    /// Since: 3.18.0
    pub const REFACTOR_MOVE: Self = Self(Cow::Borrowed("refactor.move"));
    /// Base kind for refactoring rewrite actions: 'refactor.rewrite'
    ///
    /// Example rewrite actions:
    ///
    /// - Convert JavaScript function to class
    /// - Add or remove parameter
    /// - Encapsulate field
    /// - Make method static
    /// - Move method to base class
    /// - ...
    pub const REFACTOR_REWRITE: Self = Self(Cow::Borrowed("refactor.rewrite"));
    /// Base kind for source actions: `source`
    ///
    /// Source code actions apply to the entire file.
    pub const SOURCE: Self = Self(Cow::Borrowed("source"));
    /// Base kind for an organize imports source action: `source.organizeImports`
    pub const SOURCE_ORGANIZE_IMPORTS: Self = Self(Cow::Borrowed("source.organizeImports"));
    /// Base kind for auto-fix source actions: `source.fixAll`.
    ///
    /// Fix all actions automatically fix errors that have a clear fix that do not require user input.
    /// They should not suppress errors or perform unsafe fixes such as generating new types or classes.
    ///
    /// Since: 3.15.0
    pub const SOURCE_FIX_ALL: Self = Self(Cow::Borrowed("source.fixAll"));
}

